-- =====================================================================
-- TÉCNICA · FASE 1 · EVENTOS: ORIGEN Y TUBOS · 05 — HUELLAS (SOLO LECTURA; una sola consulta, apta para el editor SQL web). Correr ANTES y DESPUÉS.
-- Antes: la fila 0 debe decir PUBLICADA, las 1 «LA PUBLICADA», la 2 «NO EXISTE»; después: APLICADO, «REEMPLAZADA» y «NUEVA». La 3 siempre «SIN CAMBIO».
-- =====================================================================
select k, v, estado from (
  select 0 as o, '0 funciones de redes (conjunto)' as k,
         (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p
           where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) as v,
         case (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p
                where p.pronamespace = 'redes'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%'))
              when '3f3c89e603629d92e1cc5065de33d0c1' then 'PUBLICADA (reportes del PTAP y Distribución; lista para este corte)' when '1ba192724c2fddcf321104700829f3cc' then 'EVENTOS: ORIGEN Y TUBOS (aplicado)' else 'OTRA: deténgase y avise' end as estado
  union all
  select 1, '1 ' || a.f || ' (se reemplaza)', md5(pg_get_functiondef(to_regprocedure(a.f))),
         case md5(pg_get_functiondef(to_regprocedure(a.f))) when a.m then 'LA PUBLICADA' when d.m then 'REEMPLAZADA (aplicado)' else 'OTRA: deténgase y avise' end
    from (values ('redes.f_evento_zona(jsonb)', '71f7f27f97954858a61fcfab9f6a692f'), ('public.geoportal_redes_evento_declarar(text,jsonb)', 'ddf3e36525c21605a4dbf36789082c92'), ('public.geoportal_redes_evento_catalogo(text)', '129674a1c44946f4c81bcff95b595353'), ('redes.f_evento_json(bigint,boolean)', '4bbabe20fdf321767e3125915b7880ea'), ('public.geoportal_redes_planta_sectores_fijar(text,text,text[],text)', '4446a2f9bf36d700330c0c2062a2bc9f'), ('redes.f_rep_columnas(text)', '73f3fbcf2bbcf893e980783226e53031'), ('redes.f_rep_eventos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', '8c6565348cac64d2bf1c21b825698024'), ('redes.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', '9ec53194c4550a39509601d9bcfe374f'), ('tecnica.f_rep_columnas(text,jsonb)', 'd178a29b3e4408b96b07bbaeae20f476'), ('tecnica.f_rep_eventos_planta(jsonb,boolean,timestamp with time zone,text,integer)', '5b97ed0684b94b94c14ec420aa1c212a'), ('tecnica.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', '5f894b795ad896a7cc965b3ec5d37745')) a(f, m) join (values ('redes.f_evento_zona(jsonb)', '795f3c6c45b34306060d375ebe1f370d'), ('public.geoportal_redes_evento_declarar(text,jsonb)', 'fdf51a96463dac4088a66632fb926d06'), ('public.geoportal_redes_evento_catalogo(text)', '845a7401e73af489e42e716241bbd06f'), ('redes.f_evento_json(bigint,boolean)', '45f59666e3984baa767aa251e20ef79a'), ('public.geoportal_redes_planta_sectores_fijar(text,text,text[],text)', '147efbf990088feecd07994db03732aa'), ('redes.f_rep_columnas(text)', 'a6955a401c14a8692d68402294db810e'), ('redes.f_rep_eventos(jsonb,boolean,timestamp with time zone,text,integer,boolean)', 'bef95e9511f4eaf360ede1023e8c40a4'), ('redes.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', '41c7b3680290ba3bcfe7a98cae9fe7dc'), ('tecnica.f_rep_columnas(text,jsonb)', '433cc539c24e1e14b07f96d79e974f65'), ('tecnica.f_rep_eventos_planta(jsonb,boolean,timestamp with time zone,text,integer)', '1f3ac41ec397b2ce20d0d818c63b0b15'), ('tecnica.f_rep_leame(text,jsonb,boolean,text,timestamp with time zone)', 'fe08987ea0b82be59420fc5d964459ff')) d(f, m) on d.f = a.f
  union all
  select 2, '2 ' || n.f || ' (nueva)', case when to_regprocedure(n.f) is not null then md5(pg_get_functiondef(to_regprocedure(n.f))) end,
         case when to_regprocedure(n.f) is null then 'NO EXISTE (sin aplicar)' when md5(pg_get_functiondef(to_regprocedure(n.f))) = n.m then 'NUEVA (aplicada)' else 'OTRA: deténgase y avise' end
    from (values ('redes.f_evento_origen(bigint)', '81107c71dfa94d8c79fef3ca595e7788'), ('redes.f_tubo_zona(text[])', 'a15f2de42924d7c6c0da5f1f73ea880e'), ('redes.f_tubo_es_distribucion()', '9d5b37643892051a53684a1cdfd82e4c'), ('public.geoportal_redes_evento_causal_fijar(text,text,text,boolean,text)', '5330bd20fe560e627d4a8532dd7e11b2'), ('public.geoportal_redes_tubo_sectores_fijar(text,text,text[],text)', '03657c4afcbcdb5374bb5812103439b6')) n(f, m)
  union all
  select 3, '3 las 31 que no se tocan (evento_contrato, aviso, SCRR, disparadores, bot, demás rutas de eventos)', null,
         case when (select count(*) from (values ('geoportal_redes_evento_anular(text,text,text)', '8947de32c9f76c9bfc937a31e8bf2c39'), ('geoportal_redes_evento_asociar(text,text,text,text,text)', 'd97df5946041079714a86de12e1d1902'), ('geoportal_redes_evento_cerrar(text,text,text,text)', '1ae6ea7e5c0c5f71b5d41f752775f343'), ('geoportal_redes_evento_contrato(text,text)', 'f82b45906c62feca8b431020284e8bbf'), ('geoportal_redes_evento_desasociar(text,text,text,text,text)', 'cf6f1f7a378e8ab653be26aa9a78a4ee'), ('geoportal_redes_evento_regreso(text,text,text,text)', 'daa542d7d0b0f8cbb09c4f4429fbfd6a'), ('geoportal_redes_evento_tipo_fijar(text,text,text,boolean,text,text,text)', '72a0f1537529089418bd981a30f2fdca'), ('geoportal_redes_evento_vista_previa(text,jsonb)', 'cb22112ec60088390648e3394f1376d7'), ('geoportal_redes_evento(text,text)', 'e1c60d1fdc53332d64db9360ed164461'), ('geoportal_redes_eventos_vigentes(text)', '30d3b3306038af969a1e7e1b75e6f5ef'), ('geoportal_redes_eventos(text,text,integer)', '5b6e1f23c3985e69cfe4908dc3752b8a'), ('geoportal_redes_reporte_iniciar(text,text,jsonb,text,boolean,text)', '05ee00808781f3af88db3d3a57c68f22'), ('geoportal_redes_reporte_pagina(text,bigint,text,integer)', '5e55735ae8f7ad024627f1393aedefdd'), ('geoportal_redes_reporte_sectores(text)', 'b4c7e051d0f41881fc24550a7297f538'), ('redes.f_evento_abierto(text,text,text)', '59df33f21167b73cbc9a5049b505859e'), ('redes.f_evento_autorizar(text,text)', '1c1dc3406cf363dbe6c7a6de06e12954'), ('redes.f_evento_candidatos(geometry,boolean,timestamp with time zone,uuid)', 'dc09e88af2c5c2daa62f2c53fa8ee842'), ('redes.f_evento_contratos(geometry,boolean,boolean)', '8dafa57412c9b41aca0a0e3652f3bf2a'), ('redes.f_evento_franja(text,timestamp with time zone,text,timestamp with time zone)', 'fb9de8c4ada4a35de44889aea9f17b62'), ('redes.f_evento_marcar(bigint[],text,text,text)', 'f067be6b5b0344e0d9c044f8ade679de'), ('redes.f_evento_reportes(bigint)', 'e9d6c5b2d72868e188e2bc5eeda47ddd'), ('redes.f_evento_tg_bot()', '857c47e052a5204c1c437c07d4cd77d1'), ('redes.f_evento_tg_campo()', '8a755c25a340e331b233ccadf99bb099'), ('redes.f_evento_tg_dano()', '430048038207e8bcfeedbf537e75faf8'), ('redes.f_evento_tg_l116()', 'a3959ab3a96e37539fd6507cddc3e075'), ('redes.f_eventos_abiertos()', '2d265a26461ea19a01e9a81bb927b120'), ('redes.f_eventos_para_avisos(timestamp with time zone)', '755cc3b1a15fbd9c82fd34991a97216a'), ('redes.f_reporte_externo_recibir_evento(jsonb)', '92be46589b80d60ce38139e3fe44550d'), ('redes.f_sector_de(geometry)', '455378c9b8cf43343ff821a2896eae37'), ('redes.f_sin_agua_para_avisos(timestamp with time zone,numeric)', '6a370c60ddcc409b06104f599110915a'), ('tecnica.f_avisos(boolean,boolean,timestamp with time zone)', 'aaa81ee57ec79080b9e76213ecea006c')) c(f, m) where md5(pg_get_functiondef(to_regprocedure(c.f))) = c.m) = 31 then 'SIN CAMBIO' else 'CAMBIARON: deténgase y avise' end
  union all
  select 4, '4 tablas nuevas (6)', null,
         case (select count(*) from pg_class where oid in (to_regclass('redes.evento_causales'), to_regclass('redes.evento_causal_eventos'), to_regclass('redes.evento_causal'),
                                                         to_regclass('redes.tubo_sectores'), to_regclass('redes.tubo_sector_eventos'), to_regclass('redes.evento_tubos')))
              when 0 then 'NO EXISTEN (sin aplicar)' when 6 then 'EXISTEN (aplicado)' else 'A MEDIAS: deténgase y avise' end
  union all
  select 5, '5 INFO sectores por planta activos · plantas con alguno · tubos de salida (tipo distribución) · eventos · eventos de planta', null,
         (select count(*) from redes.planta_sectores where activo) || ' · ' || (select count(distinct planta_id) from redes.planta_sectores where activo) || ' · '
         || (select count(*) from tecnica.puntos where tipo = 'distribucion') || ' · ' || (select count(*) from redes.eventos_suspension) || ' · '
         || (select count(*) from redes.eventos_suspension where planta_id is not null)
  union all
  select 6, '6 INFO huella de técnica (esquema tecnica y geoportal_tec_*; anótela antes y después)',
         (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p
           where p.pronamespace = 'tecnica'::regnamespace or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_tec\_%')), 'INFORMATIVA'
) t order by o, k;
